-- Auchindoun : les répliques des PNJ (Tuulani, Nyami, Kaathar, Azzakel, Teron'gor, gardien, sentinelle) reprennent le numéro de groupe que leur script appelle ; la table portait tout au groupe 3 ou une autre numérotation.
DELETE FROM `creature_text` WHERE `CreatureID` IN (79248, 77810, 76177, 75839, 75927, 77734, 76632);
DELETE FROM `creature_text` WHERE `CreatureID` = 77704 AND `GroupID` IN (32, 33);
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 77810 AND `GroupID` IN (25, 26) AND `Locale` = 'frFR';
